(* [comment removed for export] *)
Definition tob_xroom (ar : asan_run) (M : word -> option byte) (sp h : Z) : Prop :=
  L5CA.astk ar M sp (PMSPA.pm_scr h + 16) /\ shadow_zero M (sp - PMSPA.pm_scr h - 16) (PMSPA.pm_scr h / 8 + 2).

(* [comment removed for export] *)
Definition PTOB (LR : HAR.layoutR) (D : list (list Z)) (RC : list Z) : credit :=
  PM.credit_add PQATSTW.SLACK (PM.credit_add (PQATSTW.pmal LR D) (PQATSTW.pfree D (PQATSTW.fkeys3 (HAR.hlr_pc_free LR) S_FREE RA_TOBD RC))).
Definition PTOBMAX : credit := (1 + 2 * 8 + 3, 2 * 2097344).
(* [comment removed for export] *)
Definition TSPE (LR : HAR.layoutR) (t r : Z) (D : list (list Z)) (RC : list Z) : credit :=
  if Z.eqb t NEM.TAG_ENANO
  then PM.credit_add PQATSTW.SLACK (PM.credit_add (PQATSTW.pmal LR D)
         (PQATSTW.pfree D (PQATSTW.fkeys3 (HAR.hlr_pc_free LR) S_FREE RA_TOBD [] ++ PQATSTW.fkeys3 (HAR.hlr_pc_free LR) S_FREE RA_TOBD (r :: RC))))
  else PMSP.cr0.
Definition TSPEMAX : credit := (1 + 2 * 8 + 6, 2 * 2097344).

