Definition divE_specG (pc h : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r o dn oq orr fb fbd : Z) (v0 v1 d1 : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB PQRA.FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 dn -> getr R (reg 12) = Z_to_bv 64 oq -> getr R (reg 13) = Z_to_bv 64 orr ->
    getr R (reg 14) = Z_to_bv 64 1 ->
    PMSPA.aobjA FF o 32 -> o mod 8 = 0 -> PMSPA.accA M o 32 -> binl_at M o fb (PQATSS.wlen v0 v1) v0 v1 -> 1 <= v0 + 2 ^ 64 * v1 ->
    PMSPA.aobjA FF oq 32 -> oq mod 8 = 0 -> PMSPA.accA M oq 32 -> binl_at M oq 0 0%nat 0 0 ->
    PMSPA.aobjA FF orr 32 -> orr mod 8 = 0 -> PMSPA.accA M orr 32 -> binl_at M orr 0 0%nat 0 0 ->
    (o + 32 <= oq \/ oq + 32 <= o) -> (o + 32 <= orr \/ orr + 32 <= o) -> (oq + 32 <= orr \/ orr + 32 <= oq) ->
    sp <= dn -> dn + 32 <= ar_sptop ar -> dn mod 8 = 0 -> shadow_zero M dn 4 -> binl_at M dn fbd 1%nat TEN9 d1 -> Z.testbit fbd 1 = false ->
    PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (fbq' fbr' : Z) (lq : nat) (q0 q1 : Z) (lr : nat) (r0 : Z),
        regs_preserved R R' ->
        binl_at M' oq fbq' lq q0 q1 -> (lq <= 2)%nat -> Z.testbit fbq' 0 = false ->       (* [comment removed for export] *)
        binl_at M' orr fbr' lr r0 0 -> (lr <= 1)%nat -> Z.testbit fbr' 0 = false ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr h) [(oq, 32); (orr, 32)] M M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv HI LB FF LK' cr Aw M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

