    getr R (reg 8) = Z_to_bv 64 fp0 -> HAR.rchain L ar M sp fp0 RC -> sp + 16 <= fp0 < 2 ^ 64 ->   (* [comment removed for export] *)
    getr R (reg 10) = Z_to_bv 64 s -> getr R (reg 11) = Z_to_bv 64 n -> getr R (reg 12) = Z_to_bv 64 x ->
