(* [comment removed for export] *)
Definition PTD (LR : HAR.layoutR) (rd : Z) (D : list (list Z)) (RC : list Z) : credit :=
  PM.credit_add SLACK (PM.credit_add (pmal LR D) (pfree D (fkeys3 (HAR.hlr_pc_free LR) NETSA.S_FREE rd RC))).
Lemma PTOB_eq LR D RC : NETSA.PTOB LR D RC = PTD LR NETSA.RA_TOBD D RC.
Proof. reflexivity. Qed.
Lemma ptd_anti LR rd D D' RC : incl D D' -> PMSP.credit_le (PTD LR rd D' RC) (PTD LR rd D RC).
Proof.
  intros INC. unfold PTD, SLACK, pmal, pfree, PMSP.credit_le, PM.credit_add. cbn [fst snd].
  pose proof (csum_anti CMAL D D' (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A & B).
  match goal with |- context [csum (map (kcost (1, 0) D) ?ks)] => pose proof (csum_anti (1, 0) D D' ks ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A' & B') end.
  lia.
Qed.

(* [comment removed for export] *)
Lemma ptob_rng LR D RC : PMSP.credit_le PMSP.cr0 (NETSA.PTOB LR D RC) /\ PMSP.credit_le (NETSA.PTOB LR D RC) NETSA.PTOBMAX /\ PMSP.credit_le SLACK (NETSA.PTOB LR D RC).
Proof.
  unfold NETSA.PTOB, NETSA.PTOBMAX, SLACK, pmal, pfree, PMSP.credit_le, PM.credit_add, PMSP.cr0. cbn [fst snd].
  pose proof (csum_rng CMAL D (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ltac:(cbn; lia) ltac:(cbn; lia)) as (A & B).
  change (Z.of_nat (length (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A))) with 2 in A, B. change (fst CMAL) with 8 in A. change (snd CMAL) with 2097344 in B.
  match goal with |- context [csum (map (kcost (1, 0) D) ?ks)] =>
    pose proof (csum_rng (1, 0) D ks ltac:(cbn; lia) ltac:(cbn; lia)) as (A' & B'); change (Z.of_nat (length ks)) with 3 in A', B' end.
  change (fst (1, 0)) with 1 in A'. change (snd (1, 0)) with 0 in B'. lia.
Qed.
Lemma ptob_anti LR D D' RC : incl D D' -> PMSP.credit_le (NETSA.PTOB LR D' RC) (NETSA.PTOB LR D RC).
Proof.
  intros INC. unfold NETSA.PTOB, SLACK, pmal, pfree, PMSP.credit_le, PM.credit_add. cbn [fst snd].
  pose proof (csum_anti CMAL D D' (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A & B).
  match goal with |- context [csum (map (kcost (1, 0) D) ?ks)] => pose proof (csum_anti (1, 0) D D' ks ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A' & B') end.
  lia.
Qed.

(* [comment removed for export] *)
Lemma TSPE_laws LR : forall t r D RC,
  PMSP.credit_le PMSP.cr0 (NETSA.TSPE LR t r D RC) /\ PMSP.credit_le (NETSA.TSPE LR t r D RC) NETSA.TSPEMAX
  /\ (t <> NEM.TAG_ENANO -> NETSA.TSPE LR t r D RC = PMSP.cr0)
  /\ (forall D', incl D D' -> PMSP.credit_le (NETSA.TSPE LR t r D' RC) (NETSA.TSPE LR t r D RC)).
Proof.
  intros t r D RC. unfold NETSA.TSPE. destruct (Z.eqb_spec t NEM.TAG_ENANO) as [E|NE].
  - split; [| split; [| split; [intros X; exfalso; exact (X E)|]]].
    + unfold SLACK, pmal, pfree, PMSP.credit_le, PM.credit_add, PMSP.cr0. cbn [fst snd].
      pose proof (csum_rng CMAL D (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ltac:(cbn; lia) ltac:(cbn; lia)) as (A & B).
      match goal with |- context [csum (map (kcost (1, 0) D) ?ks)] => pose proof (csum_rng (1, 0) D ks ltac:(cbn; lia) ltac:(cbn; lia)) as (A' & B') end. lia.
    + unfold NETSA.TSPEMAX, SLACK, pmal, pfree, PMSP.credit_le, PM.credit_add. cbn [fst snd].
      pose proof (csum_rng CMAL D (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ltac:(cbn; lia) ltac:(cbn; lia)) as (A & B).
      change (Z.of_nat (length (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A))) with 2 in A, B. change (fst CMAL) with 8 in A. change (snd CMAL) with 2097344 in B.
      match goal with |- context [csum (map (kcost (1, 0) D) ?ks)] =>
        pose proof (csum_rng (1, 0) D ks ltac:(cbn; lia) ltac:(cbn; lia)) as (A' & B'); change (Z.of_nat (length ks)) with 6 in A', B' end.
      change (fst (1, 0)) with 1 in A'. change (snd (1, 0)) with 0 in B'. lia.
    + intros D' INC. unfold SLACK, pmal, pfree, PMSP.credit_le, PM.credit_add. cbn [fst snd].
      pose proof (csum_anti CMAL D D' (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A & B).
      match goal with |- context [csum (map (kcost (1, 0) D) ?ks)] => pose proof (csum_anti (1, 0) D D' ks ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A' & B') end.
      lia.
  - unfold PMSP.credit_le, PMSP.cr0. cbn [fst snd]. split; [lia|]. split; [unfold NETSA.TSPEMAX; cbn [fst snd]; lia|]. split; [reflexivity| intros; lia].
Qed.

(* [comment removed for export] *)
Lemma ptob_le_tspe LR r D RC RCt : (RCt = [] \/ RCt = r :: RC) -> PMSP.credit_le (NETSA.PTOB LR D RCt) (NETSA.TSPE LR NEM.TAG_ENANO r D RC).
Proof.
  intros H. unfold NETSA.TSPE. rewrite Z.eqb_refl. unfold NETSA.PTOB, pfree. rewrite csum_app.
  unfold PMSP.credit_le, PM.credit_add, SLACK. cbn [fst snd].
  pose proof (csum_rng (1, 0) D (fkeys3 (HAR.hlr_pc_free LR) NETSA.S_FREE NETSA.RA_TOBD []) ltac:(cbn; lia) ltac:(cbn; lia)) as (A0 & B0).
  pose proof (csum_rng (1, 0) D (fkeys3 (HAR.hlr_pc_free LR) NETSA.S_FREE NETSA.RA_TOBD (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia)) as (A1 & B1).
  destruct H as [-> | ->]; lia.
Qed.
(* [comment removed for export] *)
Lemma tspe_keep_of_ptob LR r D D' RC RCt cr cr' : (RCt = [] \/ RCt = r :: RC) -> incl D D' ->
  PMSP.credit_keep cr cr' (NETSA.PTOB LR D RCt) (NETSA.PTOB LR D' RCt) ->
  PMSP.credit_keep cr cr' (NETSA.TSPE LR NEM.TAG_ENANO r D RC) (NETSA.TSPE LR NEM.TAG_ENANO r D' RC).
Proof.
  intros H INC (K1 & K2). unfold NETSA.TSPE. rewrite Z.eqb_refl. unfold NETSA.PTOB, pfree in *. rewrite !csum_app in *.
  unfold PMSP.credit_keep, PM.credit_add, SLACK in *. cbn [fst snd] in *.
  pose proof (csum_anti (1, 0) D D' (fkeys3 (HAR.hlr_pc_free LR) NETSA.S_FREE NETSA.RA_TOBD []) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A0 & B0).
  pose proof (csum_anti (1, 0) D D' (fkeys3 (HAR.hlr_pc_free LR) NETSA.S_FREE NETSA.RA_TOBD (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A1 & B1).
  destruct H as [-> | ->]; lia.
Qed.

