(* [comment removed for export] *)
Lemma gpre_ptob cr : PMSP.credit_le (T D) cr -> PQATSG.gpre L LR PQATSG.OPNEW_RA_A D 64 cr.
Proof.
  intros (C1 & C2) gk Hgk. unfold PTD, PM.credit_add, SLACK in C1, C2. cbn [fst snd] in C1, C2.
  pose proof (csum_rng (1, 0) D KS ltac:(cbn; lia) ltac:(cbn; lia)) as (A' & B'). unfold pfree in C1, C2.
  assert (PN : 0 <= fst (pmal LR D) /\ 0 <= snd (pmal LR D)).
  { unfold pmal. pose proof (csum_rng CMAL D GK ltac:(cbn; lia) ltac:(cbn; lia)) as (A1 & A2). lia. }
  unfold PQATSG.gcostD, HAR.warm_ok. change (HAR.NW_LO <=? 64) with true. change (64 <=? HAR.NW_HI) with true. rewrite !andb_true_r.
  destruct (HAR.kin gk D) eqn:E.
  - unfold PQATSG.gcost, PMSP.credit_le. cbn [fst snd]. lia.
  - rewrite (cmal_gcost L C LY). unfold PMSP.credit_le, CMAL. cbn [fst snd].
    assert (PM1 : 8 <= fst (pmal LR D) /\ 2097344 <= snd (pmal LR D)).
    { unfold pmal. unfold PQATSG.GKEYS in Hgk |- *. cbn [map csum fold_right]. unfold PM.credit_add, PMSP.cr0. cbn [fst snd].
      destruct Hgk as [<-|[<-|[]]]; unfold kcost; rewrite E; unfold CMAL;
        [destruct (HAR.kin [HAR.hlr_pc_malloc LR] D)| destruct (HAR.kin (HAR.akey (HAR.hlr_pc_malloc LR) [PQATSG.OPNEW_RA_A]) D)]; unfold PMSP.cr0; cbn [fst snd]; lia. }
    lia.
Qed.

(* [comment removed for export] *)
Definition inv (cr : credit) (Dk : list (list Z)) (crk : credit) (s : Z) : Prop :=
  fst cr - fst (T D) + fst (T Dk) <= fst crk + s /\ snd cr - snd (T D) + snd (T Dk) <= snd crk.
Lemma inv_start cr : inv cr D cr 0.
Proof. unfold inv. lia. Qed.
Lemma T_anti Dk x : fst (T (x :: Dk)) <= fst (T Dk) /\ snd (T (x :: Dk)) <= snd (T Dk).
Proof. exact (ptd_anti LR rd Dk (x :: Dk) RC (PQATSTK.incl_cons_r x Dk)). Qed.
Lemma inv_malloc cr Dk crk s gk crk' :
  inv cr Dk crk s -> In gk GK -> PMSP.credit_keep crk crk' (PQATSG.gcostD L gk Dk 64) PMSP.cr0 -> inv cr (gk :: Dk) crk' (s + 1).
Proof.
  intros (I1 & I2) KIN (K1 & K2). unfold PQATSG.gcostD, HAR.warm_ok in K1, K2. change (HAR.NW_LO <=? 64) with true in K1, K2. change (64 <=? HAR.NW_HI) with true in K1, K2.
  rewrite !andb_true_r in K1, K2. unfold PMSP.cr0 in K1, K2. cbn [fst snd] in K1, K2.
  pose proof (T_anti Dk gk) as (A1 & A2).
  destruct (HAR.kin gk Dk) eqn:E.
  - unfold PQATSG.gcost in K1, K2. cbn [fst snd] in K1, K2. unfold inv. lia.
  - rewrite (cmal_gcost L C LY) in K1, K2. unfold CMAL in K1, K2. cbn [fst snd] in K1, K2.
    assert (DROP : fst (T (gk :: Dk)) + 8 <= fst (T Dk) /\ snd (T (gk :: Dk)) + 2097344 <= snd (T Dk)).
    { unfold PTD, pmal, pfree, PM.credit_add, SLACK. cbn [fst snd].
      pose proof (PQATSTK.csum_drop CMAL Dk gk GK ltac:(cbn; lia) ltac:(cbn; lia) KIN E) as (B1 & B2). change (fst CMAL) with 8 in B1. change (snd CMAL) with 2097344 in B2.
      pose proof (csum_anti (1, 0) Dk (gk :: Dk) KS ltac:(cbn; lia) ltac:(cbn; lia) (PQATSTK.incl_cons_r gk Dk)) as (B3 & B4). lia. }
    unfold inv. lia.
Qed.
Lemma inv_free cr Dk crk s Kt :
  inv cr Dk crk s -> In Kt KS -> inv cr (Kt :: Dk) (if HAR.warm_ok Kt Dk 64 then (fst crk + 1, snd crk) else crk) (s - 1).
Proof.
  intros (I1 & I2) KIN. unfold HAR.warm_ok. change (HAR.NW_LO <=? 64) with true. change (64 <=? HAR.NW_HI) with true. rewrite !andb_true_r.
  pose proof (T_anti Dk Kt) as (A1 & A2).
  destruct (HAR.kin Kt Dk) eqn:E.
  - unfold inv. cbn [fst snd]. lia.
  - assert (DROP : fst (T (Kt :: Dk)) + 1 <= fst (T Dk)).
    { unfold PTD, pmal, pfree, PM.credit_add, SLACK. cbn [fst snd].
      pose proof (PQATSTK.csum_drop (1, 0) Dk Kt KS ltac:(cbn; lia) ltac:(cbn; lia) KIN E) as (B1 & _). change (fst (1, 0)) with 1 in B1.
      pose proof (csum_anti CMAL Dk (Kt :: Dk) GK ltac:(cbn; lia) ltac:(cbn; lia) (PQATSTK.incl_cons_r Kt Dk)) as (B3 & B4). lia. }
    unfold inv. lia.
Qed.

(* [comment removed for export] *)
Lemma tob_keep0 cr : PMSP.credit_keep cr cr (T D) (T D) /\ incl D D.
Proof. split; [unfold PMSP.credit_keep; lia| apply incl_refl]. Qed.
(* [comment removed for export] *)
Lemma tob_keep1 cr cr1 gk Kt :
  In gk GK -> PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk D 64) PMSP.cr0 -> In Kt KS ->
  let D1 := gk :: D in
  let cr2 := (if HAR.warm_ok Kt D1 64 then (fst cr1 + 1, snd cr1) else cr1) in
  PMSP.credit_keep cr cr2 (T D) (T (Kt :: D1)) /\ incl D (Kt :: D1).
Proof.
  intros KIN CK1 HK. cbn zeta.
  pose proof (inv_malloc cr D cr 0 gk cr1 (inv_start cr) KIN CK1) as I1.
  pose proof (inv_free cr (gk :: D) cr1 (0 + 1) Kt I1 HK) as I2.
  destruct I2 as (J1 & J2). split.
  { unfold PMSP.credit_keep. destruct (HAR.warm_ok Kt (gk :: D) 64); cbn [fst snd] in J1, J2 |- *; lia. }
  intros x Hx. do 2 right. exact Hx.
Qed.
