Lemma rchain_keep (M M' : mem) lo fp RC :
  HAR.rchain L ar M lo fp RC -> 16 <= lo -> ar_stack_top ar <= 2 ^ 47 ->
  (forall a, fp - 16 <= a < ar_stack_top ar -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
