(* [comment removed for export] *)
Lemma mparser_set_topS op ois s pre t t' :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 -> PQMA.p_stk s = pre ++ [t] ->
  mem_grows M M' -> PMFA.agA M M' op PQMA.PSIZE ->
  (forall B m, In (B, m) (PQAKOA.rest_own s) -> 0 <= B /\ B + m <= 2 ^ 64 /\ PMFA.agA M M' B m) ->
  0 <= PQMA.p_sb s -> PQMA.p_sb s + PQMA.PSZ * 2 ^ PQMA.p_sk s <= 2 ^ 64 ->
  (forall i, PQMA.p_sb s <= i < PQMA.p_sb s + PQMA.PSZ * 2 ^ PQMA.p_sk s ->
             ~ (PQMA.p_sb s + PQMA.PSZ * Z.of_nat (length pre) <= i < PQMA.p_sb s + PQMA.PSZ * Z.of_nat (length pre) + PQMA.PSZ) -> snt i) ->
  PMFA.agsh M M' (PQMA.p_sb s) (PQMA.PSZ * 2 ^ PQMA.p_sk s) ->
  PQMA.mstate_at segs M' (PQMA.p_sb s + PQMA.PSZ * Z.of_nat (length pre)) t' ->
