(* [comment removed for export] *)
Definition Wobj (s1 : PQMA.mpst) (a : Z) : Prop :=
  (sp - SCR <= a < sp) \/ (fb + 600 <= a < fb + 608) \/ (fb + 968 <= a < fb + 992) \/ (exists q m, In (q, m) (PQMA.mparser_own s1) /\ q <= a < q + m).
Lemma step_keep RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (M3 : mem) model3 (W : Z -> Prop) s3 :
  lp_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  ri_inv (HIk Dc) (mown s1 sa1 ++ LBX) FF' LK1 cr1 Aw1 M3 (vml_of model3) -> L5CA.amodel_ok Aw1 model3 -> model_rt model1 model3 -> mem_grows M1 M3 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  (forall a, W a -> ~ ocell a /\ Wobj s1 a) ->
  mparser_at M3 (fb + 592) (fb + 96) s3 -> PQMA.mparser_own s3 = PQMA.mparser_own s1 -> PQMA.p_src s3 = PQMA.p_src s1 -> PQMA.mgrow_ok s3 ->
  lp_mem RC Dc M3 model3 LK1 Aw1 s3 sa1 sm1 e1 cr1 b1
  /\ (forall a, sp - 16 <= a < ar_stack_top ar -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)).
Proof using All.
