(* [comment removed for export] *)
Lemma lp_piece_hdr RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) (W : Z -> Prop) (mo dn dp : Z) :
  lp_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, W a -> ~ ocell a /\ ((sp - SCR <= a < sp) \/ (fb + 600 <= a < fb + 608))) ->
  (L5.u8_at RSEGS M2v (fb + 600) mo \/ (mo = PQMA.p_more s1 /\ ~ W (fb + 600))) -> (mo = 0 \/ mo = 1) ->
  (L5.u8_at RSEGS M2v (fb + 601) dn \/ (dn = PQMA.p_done s1 /\ ~ W (fb + 601))) -> (dn = 0 \/ dn = 1) ->
  (L5.u32_at RSEGS M2v (fb + 604) dp \/ (dp = PQMA.p_depth s1 /\ forall a, fb + 604 <= a < fb + 608 -> ~ W a)) -> 0 <= dp <= PQMA.MAX_DEPTH + 1 ->
  (forall (M3 : mem) model3,
      lp_mem RC Dc M3 model3 LK1 Aw1 (set_hdr s1 mo dn dp) sa1 sm1 e1 cr1 b1 ->
      ahid Aw1 model3 = ahid Aw1 model1 -> mrestrict (ahid Aw1 model1) M3 = M2v ->
      (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> mem_grows M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
