(* [comment removed for export] *)
Lemma top_facts RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 pre t :
  lp_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 -> PQMA.p_stk s1 = pre ++ [t] ->
  let MV := mrestrict (ahid Aw1 model1) M1 in let b := PQMA.p_sb s1 in let T := PQMA.p_sb s1 + PQMA.PSZ * Z.of_nat (length pre) in
  (L5.u64_at RSEGS MV (fb + 968) b /\ L5.u64_at RSEGS MV (fb + 976) (T + 24) /\ L5.u64_at RSEGS MV (fb + 984) (b + PQMA.PSZ * 2 ^ PQMA.p_sk s1))
  /\ (4096 <= b /\ (b + PQMA.PSZ * 2 ^ PQMA.p_sk s1 <= 65536 \/ 7036928 <= b) /\ b <= T /\ T + 24 <= b + PQMA.PSZ * 2 ^ PQMA.p_sk s1 /\ b + PQMA.PSZ * 2 ^ PQMA.p_sk s1 <= ahl_ceil ar /\ ahl_ceil ar + 4096 <= sp - SCR /\ sp <= 2 ^ 47
      /\ b mod 16 = 0 /\ T mod 8 = 0 /\ (b + PQMA.PSZ * 2 ^ PQMA.p_sk s1 <= BIGSHADOW_LO \/ BIGSHADOW_HI <= b) /\ 0 <= PQMA.p_sk s1 <= 11 /\ Z.of_nat (length pre) + 1 <= 2 ^ PQMA.p_sk s1)
  /\ (L5KA.zeros_at MV (T / 8 + 2147450880) 3 /\ L5.writable RSEGS MV b (PQMA.PSZ * 2 ^ PQMA.p_sk s1) /\ avis (ahid Aw1 model1) b (PQMA.PSZ * 2 ^ PQMA.p_sk s1))
  /\ (L5.u32_at RSEGS MV T (PQMA.ms_mode t) /\ L5.u64_at RSEGS MV (T + 8) (PQMA.ms_len t) /\ L5.u64_at RSEGS MV (T + 16) (PQMA.ms_idx t))
