(* [comment removed for export] *)
Lemma lp_piece_top RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) (W : Z -> Prop) pre t t' :
  lp_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 -> PQMA.p_stk s1 = pre ++ [t] ->
  let T := PQMA.p_sb s1 + PQMA.PSZ * Z.of_nat (length pre) in
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, W a -> ~ ocell a /\ ((sp - SCR <= a < sp) \/ (T <= a < T + 24))) ->
  (L5.u32_at RSEGS M2v T (PQMA.ms_mode t') \/ (PQMA.ms_mode t' = PQMA.ms_mode t /\ forall a, T <= a < T + 4 -> ~ W a)) ->
  (L5.u64_at RSEGS M2v (T + 8) (PQMA.ms_len t') \/ (PQMA.ms_len t' = PQMA.ms_len t /\ forall a, T + 8 <= a < T + 16 -> ~ W a)) ->
  (L5.u64_at RSEGS M2v (T + 16) (PQMA.ms_idx t') \/ (PQMA.ms_idx t' = PQMA.ms_idx t /\ forall a, T + 16 <= a < T + 24 -> ~ W a)) ->
  (forall (M3 : mem) model3,
      lp_mem RC Dc M3 model3 LK1 Aw1 (set_stk s1 (pre ++ [t'])) sa1 sm1 e1 cr1 b1 ->
      ahid Aw1 model3 = ahid Aw1 model1 -> mrestrict (ahid Aw1 model1) M3 = M2v ->
      (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> mem_grows M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
