Lemma callee_entry Dc BX Mc modelc LKc crc Ac (R1 : bvmap 5 word) (spx ra hc : Z) :
  PQAKUF.binv L ar HIk Dc M model LBX FF LK Aw sp SCR spc own F 1 WR BX Mc modelc LKc crc Ac ->
  0 <= hc <= 10 -> spc - 32 <= spx <= spc -> spx mod 16 = 0 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spx ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
