(* [comment removed for export] *)
Lemma callee_frame BXa (M1 M4 : mem) (spx SCRc : Z) (Wc : list L5.range) :
  L5CA.ahpres L ar (BXa ++ LBX) FF' spx SCRc Wc M1 M4 -> spc - 32 <= spx <= spc ->
  (forall rr a, In rr Wc -> L5.in_rng rr a -> a < ahl_ceil ar) ->
