(* [comment removed for export] *)
Lemma lp_call_ri RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (ra : Z) :
  PQRAR.read_item_specFR L ar HIk tsp ->
  lp_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  PQMA.cpl s1 (NEMA.ae_a sa1) -> PQMA.acct n s1 (NEMA.ae_a sa1) sm1 -> NEMA.oacct n s1 sa1 sm1 -> NEMA.ebound sa1 -> (b1 = false -> NEMA.bal sa1) ->
  PQRA.minv_d 0 s1 -> PQRA.bb_room s1 sm1 ->
  PMSP.credit_le (PM.credit_add (PM.credit_add (pot_runA s1 sa1) (PMSPA.scA L PNRNA.TSRES_ME)) (tsp Dc RC)) cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> In ra PQRAR.RS_A -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) -> getr R1 (reg 8) = Z_to_bv 64 sp ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 592) -> getr R1 (reg 11) = Z_to_bv 64 (fb + 992) -> getr R1 (reg 12) = Z_to_bv 64 (fb + 1232) ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3 D3,
      regs_preserved R1 R2 -> incl Dc D3 ->
      lp_mem RC D3 M3 model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3 ->
      ((b3 = true)
       \/ (b3 = false /\ PQMA.cpl s3 (NEMA.ae_a sa3) /\ PQMA.acct n s3 (NEMA.ae_a sa3) sm3 /\ NEMA.oacct n s3 sa3 sm3 /\ NEMA.ebound sa3 /\ NEMA.bal sa3
           /\ PQRA.minv_d 0 s3 /\ PNRNA.mprog_item R2 M3 s1 s3 sa1 sa3 sm1 sm3 /\ PQRA.room_keep s1 s3 sm1 sm3)) ->
      PMSP.credit_keep cr1 cr3 (PM.credit_add (pot_runA s1 sa1) (tsp Dc RC)) (PM.credit_add (pot_runA s3 sa3) (tsp D3 RC)) ->
      (forall a, spc <= a < ar_stack_top ar -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
