(* [comment removed for export] *)
Lemma lp_pop RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 fx2 : FPState) R1 R2 (pc1 : Z) (M2v : mem) (W : Z -> Prop) pre t (mo ra : Z) :
  PQSAXQ.ann_shrink_spec RSEGS AD L ar (HIk Dc) 0xc0f48 ->
  lp_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 -> PQMA.p_stk s1 = pre ++ [t] ->
  let T := PQMA.p_sb s1 + PQMA.PSZ * Z.of_nat (length pre) in
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 0xc0f48 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ W a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, W a -> ~ ocell a /\ ((sp - SCR <= a < sp) \/ a = fb + 600 \/ (fb + 976 <= a < fb + 984))) ->
  L5.u64_at RSEGS M2v (fb + 976) T ->
  (L5.u8_at RSEGS M2v (fb + 600) mo \/ (mo = PQMA.p_more s1 /\ ~ W (fb + 600))) -> (mo = 0 \/ mo = 1) ->
  getr R2 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R2 (reg 2) = Z_to_bv 64 spc ->
  getr R2 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R2 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R2 (reg 10) = Z_to_bv 64 (fb + 968) -> getr R2 (reg 11) = Z_to_bv 64 (Z.of_nat (length pre) + 1) ->
  (forall (fx3 : FPState) R3 (M3 : mem) model3 LK3 Aw3,
      regs_preserved R2 R3 ->
      lp_mem RC Dc M3 model3 LK3 Aw3 (set_stk (set_hdr s1 mo (PQMA.p_done s1) (PQMA.p_depth s1)) pre) sa1 sm1 e1 cr1 b1 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 ra M3 model3) K) ->
