Lemma lp_fin RC Dc M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 b5 (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) :
  lp_mem RC Dc M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 b5 ->
  msteps RSEGS (st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (st fx9 R9 r M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ PQAKUF.WretX F fl 1 (fun _ => False) a -> M9v (Z_to_bv 64 a) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 a)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  regs_preserved R R9 ->
  PMSP.credit_keep cr cr5 (PM.credit_add (pot_runA s sa) TSRESA) PMSP.cr0 ->
