(* [comment removed for export] *)
Definition LIN (L : asan_layout) (n : Z) : credit := (hl_k_per_malloc L, hl_b_lin L * n + hl_b_overhead L).
Fixpoint csum {X : Type} (f : X -> credit) (l : list X) : credit :=
  match l with [] => PMSP.cr0 | x :: l' => PM.credit_add (f x) (csum f l') end.
Definition cmul (k : Z) (c : credit) : credit := (k * fst c, k * snd c).

(* [comment removed for export] *)
Definition CANDW (RS : list Z) (RC0 : list Z) : list (list Z) := [] :: map (fun ri => ri :: RC0) RS.
Definition CANDF (LR : HAR.layoutR) (rad : Z) (RS RC0 : list Z) : list (list Z) :=
  [HAR.hlr_pc_free LR] :: map (fun RC => HAR.akey (HAR.hlr_pc_free LR) (rad :: RC)) (CANDW RS RC0).

Definition ind1 (D : list (list Z)) (k : list Z) : credit := if HAR.kin k D then PMSP.cr0 else (1, 0).
Definition indL (L : asan_layout) (D : list (list Z)) (k : list Z) : credit := if HAR.kin k D then PMSP.cr0 else LIN L 64.

Definition T12G (L : asan_layout) (LR : HAR.layoutR) (gra raw rad : Z) (RS : list Z)
           (tswe : list (list Z) -> Z -> list Z -> credit) (D : list (list Z)) (RC0 : list Z) : credit :=
  PM.credit_add (1, 0)
    (PM.credit_add (csum (indL L D) (PQATSG.GKEYS LR gra))
       (PM.credit_add (csum (ind1 D) (CANDF LR rad RS RC0))
                      (csum (fun RC => tswe D raw RC) (CANDW RS RC0)))).

(* [comment removed for export] *)
Definition T12MAXG (L : asan_layout) (nrs : Z) (TSWMAX : credit) : credit :=
  PM.credit_add (1, 0) (PM.credit_add (cmul 2 (LIN L 64)) (PM.credit_add (nrs + 2, 0) (cmul (nrs + 1) TSWMAX))).

(* [comment removed for export] *)
Definition tswe_laws (tswe : list (list Z) -> Z -> list Z -> credit) (TSWMAX : credit) : Prop :=
  (forall D r RC, PMSP.credit_le PMSP.cr0 (tswe D r RC) /\ PMSP.credit_le (tswe D r RC) TSWMAX)
  /\ (forall D D' r RC, incl D D' -> PMSP.credit_le (tswe D' r RC) (tswe D r RC)).

(* [comment removed for export] *)
Lemma kin_true_In k D : HAR.kin k D = true <-> In k D.
Proof.
  unfold HAR.kin. rewrite existsb_exists. split.
  - intros (x & Hx & E). destruct (list_eq_dec Z.eq_dec x k) as [->|]; [exact Hx| discriminate].
  - intros H. exists k. split; [exact H|]. destruct (list_eq_dec Z.eq_dec k k) as [_|N]; [reflexivity| exfalso; apply N; reflexivity].
Qed.
Lemma kin_mono k D D' : incl D D' -> HAR.kin k D = true -> HAR.kin k D' = true.
Proof. intros I H. apply kin_true_In. apply I. apply kin_true_In. exact H. Qed.

Lemma csum_nonneg {X} (f : X -> credit) l : (forall x, In x l -> PMSP.credit_le PMSP.cr0 (f x)) -> PMSP.credit_le PMSP.cr0 (csum f l).
Proof.
  induction l as [|x l IH]; intros H; cbn [csum]; [unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia|].
  pose proof (H x (or_introl eq_refl)) as Hx. assert (IH' := IH (fun y Hy => H y (or_intror Hy))). unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma csum_le {X} (f g : X -> credit) l : (forall x, In x l -> PMSP.credit_le (f x) (g x)) -> PMSP.credit_le (csum f l) (csum g l).
Proof.
  induction l as [|x l IH]; intros H; cbn [csum]; [unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia|].
  pose proof (H x (or_introl eq_refl)) as Hx. assert (IH' := IH (fun y Hy => H y (or_intror Hy))). unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma csum_bound {X} (f : X -> credit) (b : credit) l :
  (forall x, In x l -> PMSP.credit_le (f x) b) -> PMSP.credit_le PMSP.cr0 b -> PMSP.credit_le (csum f l) (cmul (Z.of_nat (length l)) b).
Proof.
  induction l as [|x l IH]; intros H Hb; cbn [csum length]; [unfold PMSP.credit_le, PMSP.cr0, cmul in *; cbn [fst snd] in *; lia|].
  pose proof (H x (or_introl eq_refl)) as Hx. assert (IH' := IH (fun y Hy => H y (or_intror Hy)) Hb).
  rewrite Nat2Z.inj_succ. unfold PMSP.credit_le, PMSP.cr0, cmul, PM.credit_add in *. cbn [fst snd] in *. nia.
Qed.
(* [comment removed for export] *)
Lemma csum_ind1_drop D D' k l :
  In k l -> HAR.kin k D = false -> incl (k :: D) D' ->
  PMSP.credit_le (PM.credit_add (csum (ind1 D') l) (1, 0)) (csum (ind1 D) l).
Proof.
  induction l as [|x l IH]; intros Hin Hk I; [destruct Hin|].
  assert (MONO : forall y, PMSP.credit_le (ind1 D' y) (ind1 D y)).
  { intros y. unfold ind1. destruct (HAR.kin y D) eqn:E.
    - rewrite (kin_mono y D D' (fun z Hz => I z (or_intror Hz)) E). unfold PMSP.credit_le; cbn [fst snd]; lia.
    - destruct (HAR.kin y D'); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia. }
  cbn [csum].
  destruct Hin as [->|Hin].
  - assert (K' : HAR.kin k D' = true) by (apply kin_true_In; apply I; left; reflexivity).
    unfold ind1 at 1 3. rewrite K', Hk. pose proof (csum_le (ind1 D') (ind1 D) l (fun y _ => MONO y)) as LE.
    unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
  - pose proof (IH Hin Hk I) as LE. pose proof (MONO x) as MX. unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma csum_indL_drop L D D' k l :
  In k l -> HAR.kin k D = false -> incl (k :: D) D' -> PMSP.credit_le PMSP.cr0 (LIN L 64) ->
  PMSP.credit_le (PM.credit_add (csum (indL L D') l) (LIN L 64)) (csum (indL L D) l).
Proof.
  induction l as [|x l IH]; intros Hin Hk I NN; [destruct Hin|].
  assert (MONO : forall y, PMSP.credit_le (indL L D' y) (indL L D y)).
  { intros y. unfold indL. destruct (HAR.kin y D) eqn:E.
    - rewrite (kin_mono y D D' (fun z Hz => I z (or_intror Hz)) E). unfold PMSP.credit_le; cbn [fst snd]; lia.
    - destruct (HAR.kin y D'); unfold PMSP.credit_le, PMSP.cr0 in *; cbn [fst snd] in *; lia. }
  cbn [csum].
  destruct Hin as [->|Hin].
  - assert (K' : HAR.kin k D' = true) by (apply kin_true_In; apply I; left; reflexivity).
    unfold indL at 1 3. rewrite K', Hk. pose proof (csum_le (indL L D') (indL L D) l (fun y _ => MONO y)) as LE.
    unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
  - pose proof (IH Hin Hk I NN) as LE. pose proof (MONO x) as MX. unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.

Section Laws.
Variables (L : asan_layout) (LR : HAR.layoutR) (gra raw rad : Z) (RS : list Z) (tswe : list (list Z) -> Z -> list Z -> credit) (TSWMAX : credit).
Hypothesis LNN : 0 <= hl_k_per_malloc L /\ 0 <= hl_b_lin L /\ 0 <= hl_b_overhead L.
Hypothesis TW : tswe_laws tswe TSWMAX.
Let T12 := T12G L LR gra raw rad RS tswe.

Lemma LIN_nonneg : PMSP.credit_le PMSP.cr0 (LIN L 64).
Proof. unfold PMSP.credit_le, PMSP.cr0, LIN; cbn. clear - LNN. nia. Qed.

Lemma T12_floor D RC0 : PMSP.credit_le (1, 0) (T12 D RC0).
Proof.
  unfold T12, T12G.
  pose proof (csum_nonneg (indL L D) (PQATSG.GKEYS LR gra) ltac:(intros x _; unfold indL; destruct (HAR.kin x D); [unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia| exact LIN_nonneg])) as B.
  pose proof (csum_nonneg (ind1 D) (CANDF LR rad RS RC0) ltac:(intros x _; unfold ind1; destruct (HAR.kin x D); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia)) as C.
  pose proof (csum_nonneg (fun RC => tswe D raw RC) (CANDW RS RC0) ltac:(intros x _; exact (proj1 (proj1 TW D raw x)))) as W.
  unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12_nonneg D RC0 : PMSP.credit_le PMSP.cr0 (T12 D RC0).
Proof. pose proof (T12_floor D RC0) as F. unfold PMSP.credit_le, PMSP.cr0 in *; cbn [fst snd] in *. lia. Qed.

Lemma len_CANDW RC0 : length (CANDW RS RC0) = Datatypes.S (length RS).
Proof. unfold CANDW. cbn [length]. rewrite length_map. reflexivity. Qed.
Lemma len_CANDF RC0 : length (CANDF LR rad RS RC0) = Datatypes.S (Datatypes.S (length RS)).
Proof. unfold CANDF. cbn [length]. rewrite length_map, len_CANDW. reflexivity. Qed.

Lemma T12_max D RC0 : length (PQATSG.GKEYS LR gra) = 2%nat -> PMSP.credit_le (T12 D RC0) (T12MAXG L (Z.of_nat (length RS)) TSWMAX).
Proof.
  intros LG. unfold T12, T12G, T12MAXG.
  pose proof (csum_bound (indL L D) (LIN L 64) (PQATSG.GKEYS LR gra)
                ltac:(intros x _; unfold indL; destruct (HAR.kin x D); [exact LIN_nonneg| unfold PMSP.credit_le; cbn [fst snd]; lia]) LIN_nonneg) as B.
  rewrite LG in B.
  pose proof (csum_bound (ind1 D) (1, 0) (CANDF LR rad RS RC0)
                ltac:(intros x _; unfold ind1; destruct (HAR.kin x D); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia) ltac:(unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia)) as C.
  rewrite len_CANDF in C.
  pose proof (csum_bound (fun RC => tswe D raw RC) TSWMAX (CANDW RS RC0) ltac:(intros x _; exact (proj2 (proj1 TW D raw x)))
                ltac:(pose proof (proj1 TW D raw []) as [X Y]; unfold PMSP.credit_le, PMSP.cr0 in *; cbn [fst snd] in *; lia)) as W.
  rewrite len_CANDW in W.
  unfold PMSP.credit_le, PMSP.cr0, PM.credit_add, cmul, LIN in *; cbn [fst snd] in *. rewrite !Nat2Z.inj_succ in *. clear - B C W LNN. nia.
Qed.

Lemma T12_anti D D' RC0 : incl D D' -> PMSP.credit_le (T12 D' RC0) (T12 D RC0).
Proof.
  intros I. unfold T12, T12G.
  pose proof (csum_le (indL L D') (indL L D) (PQATSG.GKEYS LR gra)
    ltac:(intros x _; unfold indL; destruct (HAR.kin x D) eqn:E; [rewrite (kin_mono x D D' I E); unfold PMSP.credit_le; cbn [fst snd]; lia| destruct (HAR.kin x D'); [exact LIN_nonneg| unfold PMSP.credit_le; cbn [fst snd]; lia]])) as B.
  pose proof (csum_le (ind1 D') (ind1 D) (CANDF LR rad RS RC0)
    ltac:(intros x _; unfold ind1; destruct (HAR.kin x D) eqn:E; [rewrite (kin_mono x D D' I E); unfold PMSP.credit_le; cbn [fst snd]; lia| destruct (HAR.kin x D'); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia])) as C.
  pose proof (csum_le (fun RC => tswe D' raw RC) (fun RC => tswe D raw RC) (CANDW RS RC0) ltac:(intros x _; exact (proj2 TW D D' raw x I))) as W.
  unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.

(* [comment removed for export] *)
Lemma T12_gpre D RC0 gk : In gk (PQATSG.GKEYS LR gra) -> PMSP.credit_le (PQATSG.gcostD L gk D 64) (T12 D RC0).
Proof.
  intros Hg. unfold PQATSG.gcostD, PQATSG.gcost, HAR.warm_ok. pose proof (T12_floor D RC0) as F.
  destruct (HAR.kin gk D) eqn:K; cbn [andb].
  - change (HAR.NW_LO <=? 64) with true. change (64 <=? HAR.NW_HI) with true. cbn. exact F.
  - unfold T12, T12G in *.
    assert (B : PMSP.credit_le (LIN L 64) (csum (indL L D) (PQATSG.GKEYS LR gra))).
    { clear F. induction (PQATSG.GKEYS LR gra) as [|x l IH]; [destruct Hg|]. cbn [csum].
      pose proof (csum_nonneg (indL L D) l ltac:(intros y _; unfold indL; destruct (HAR.kin y D); [unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia| exact LIN_nonneg])) as NN.
      destruct Hg as [->|Hg].
      + unfold indL at 1. rewrite K. unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *; lia.
      + pose proof (IH Hg) as LE.
        assert (MX : PMSP.credit_le PMSP.cr0 (indL L D x)) by (unfold indL; destruct (HAR.kin x D); [unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia| exact LIN_nonneg]).
        unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *; lia. }
    pose proof (csum_nonneg (ind1 D) (CANDF LR rad RS RC0) ltac:(intros x _; unfold ind1; destruct (HAR.kin x D); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia)) as C.
    pose proof (csum_nonneg (fun RC => tswe D raw RC) (CANDW RS RC0) ltac:(intros x _; exact (proj1 (proj1 TW D raw x)))) as W.
    unfold PMSP.credit_le, PMSP.cr0, PM.credit_add, LIN in *; cbn [fst snd] in *. lia.
Qed.

(* [comment removed for export] *)
Lemma T12_grow D RC0 gk : In gk (PQATSG.GKEYS LR gra) ->
  PMSP.credit_le (PM.credit_add (T12 (gk :: D) RC0) (PM.credit_add (PQATSG.gcostD L gk D 64) (-1, 0))) (T12 D RC0).
Proof.
  intros Hg. unfold PQATSG.gcostD, PQATSG.gcost, HAR.warm_ok.
  assert (I : incl D (gk :: D)) by (intros z Hz; right; exact Hz).
  destruct (HAR.kin gk D) eqn:K; cbn [andb].
  - change (HAR.NW_LO <=? 64) with true. change (64 <=? HAR.NW_HI) with true.
    pose proof (T12_anti D (gk :: D) RC0 I) as A. unfold PMSP.credit_le, PM.credit_add in *; cbn [andb fst snd] in *. lia.
  - unfold T12, T12G.
    pose proof (csum_indL_drop L D (gk :: D) gk (PQATSG.GKEYS LR gra) Hg K (incl_refl _) LIN_nonneg) as B.
    pose proof (csum_le (ind1 (gk :: D)) (ind1 D) (CANDF LR rad RS RC0)
      ltac:(intros x _; unfold ind1; destruct (HAR.kin x D) eqn:E; [rewrite (kin_mono x D (gk :: D) I E); unfold PMSP.credit_le; cbn [fst snd]; lia| destruct (HAR.kin x (gk :: D)); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia])) as C.
    pose proof (csum_le (fun RC => tswe (gk :: D) raw RC) (fun RC => tswe D raw RC) (CANDW RS RC0) ltac:(intros x _; exact (proj2 TW D (gk :: D) raw x I))) as W.
    unfold PMSP.credit_le, PM.credit_add, LIN in *; cbn [fst snd] in *. lia.
Qed.

(* [comment removed for export] *)
Lemma T12_ws D RC0 RC : In RC (CANDW RS RC0) ->
  PMSP.credit_le (PM.credit_add (tswe D raw RC) (1, 0)) (T12 D RC0)
  /\ (forall D', incl D D' ->
        PMSP.credit_le (PM.credit_add (T12 D' RC0) (tswe D raw RC)) (PM.credit_add (T12 D RC0) (tswe D' raw RC))).
Proof.
  intros Hin. unfold T12, T12G.
  assert (ONE : forall Dx, PMSP.credit_le (tswe Dx raw RC) (csum (fun RC' => tswe Dx raw RC') (CANDW RS RC0))).
  { intros Dx. induction (CANDW RS RC0) as [|x l IH]; [destruct Hin|]. cbn [csum].
    pose proof (csum_nonneg (fun RC' => tswe Dx raw RC') l ltac:(intros y _; exact (proj1 (proj1 TW Dx raw y)))) as NN.
    destruct Hin as [->|Hin'].
    - unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *; lia.
    - pose proof (IH Hin') as LE. pose proof (proj1 (proj1 TW Dx raw x)) as NX. unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *; lia. }
  split.
  - pose proof (ONE D) as O1.
    pose proof (csum_nonneg (indL L D) (PQATSG.GKEYS LR gra) ltac:(intros x _; unfold indL; destruct (HAR.kin x D); [unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia| exact LIN_nonneg])) as B.
    pose proof (csum_nonneg (ind1 D) (CANDF LR rad RS RC0) ltac:(intros x _; unfold ind1; destruct (HAR.kin x D); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia)) as C.
    unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
  - intros D' I.
    pose proof (csum_le (indL L D') (indL L D) (PQATSG.GKEYS LR gra)
      ltac:(intros x _; unfold indL; destruct (HAR.kin x D) eqn:E; [rewrite (kin_mono x D D' I E); unfold PMSP.credit_le; cbn [fst snd]; lia| destruct (HAR.kin x D'); [exact LIN_nonneg| unfold PMSP.credit_le; cbn [fst snd]; lia]])) as B.
    pose proof (csum_le (ind1 D') (ind1 D) (CANDF LR rad RS RC0)
      ltac:(intros x _; unfold ind1; destruct (HAR.kin x D) eqn:E; [rewrite (kin_mono x D D' I E); unfold PMSP.credit_le; cbn [fst snd]; lia| destruct (HAR.kin x D'); unfold PMSP.credit_le, PMSP.cr0; cbn [fst snd]; lia])) as C.
    (* [comment removed for export] *)
    assert (SPLIT : forall Dx Dy, (forall y, PMSP.credit_le (tswe Dy raw y) (tswe Dx raw y)) ->
              PMSP.credit_le (PM.credit_add (csum (fun RC' => tswe Dy raw RC') (CANDW RS RC0)) (tswe Dx raw RC))
                             (PM.credit_add (csum (fun RC' => tswe Dx raw RC') (CANDW RS RC0)) (tswe Dy raw RC))).
    { intros Dx Dy MONO. clear ONE B C. induction (CANDW RS RC0) as [|x l IH]; [destruct Hin|]. cbn [csum].
      destruct Hin as [->|Hin'].
      - pose proof (csum_le (fun RC' => tswe Dy raw RC') (fun RC' => tswe Dx raw RC') l (fun y _ => MONO y)) as LE.
        unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *; lia.
      - pose proof (IH Hin') as LE. pose proof (MONO x) as MX. unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *; lia. }
    pose proof (SPLIT D D' (fun y => proj2 TW D D' raw y I)) as W.
    unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.

(* [comment removed for export] *)
Lemma T12_free D RC0 Kt D2 : In Kt (CANDF LR rad RS RC0) -> incl (Kt :: D) D2 ->
  PMSP.credit_le (PM.credit_add (T12 D2 RC0) (if HAR.kin Kt D then (0, 0) else (1, 0))) (T12 D RC0).
Proof.
  intros Hin I2. assert (I : incl D D2) by (intros z Hz; apply I2; right; exact Hz).
  destruct (HAR.kin Kt D) eqn:K.
  - pose proof (T12_anti D D2 RC0 I) as A. unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
  - unfold T12, T12G.
    pose proof (csum_le (indL L D2) (indL L D) (PQATSG.GKEYS LR gra)
      ltac:(intros x _; unfold indL; destruct (HAR.kin x D) eqn:E; [rewrite (kin_mono x D D2 I E); unfold PMSP.credit_le; cbn [fst snd]; lia| destruct (HAR.kin x D2); [exact LIN_nonneg| unfold PMSP.credit_le; cbn [fst snd]; lia]])) as B.
    pose proof (csum_ind1_drop D D2 Kt (CANDF LR rad RS RC0) Hin K I2) as C.
    pose proof (csum_le (fun RC => tswe D2 raw RC) (fun RC => tswe D raw RC) (CANDW RS RC0) ltac:(intros x _; exact (proj2 TW D D2 raw x I))) as W.
    unfold PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
End Laws.
End PQATSP.

(* [comment removed for export] *)
Module PQATSPa.
Definition RA_WS12 : Z := 0xd20d8.
Definition RA_DEL12 : Z := 0xd21e0.
Definition T12 (L : asan_layout) (LR : HAR.layoutR) (tswe : list (list Z) -> Z -> list Z -> credit) : list (list Z) -> list Z -> credit :=
  PQATSP.T12G L LR PQATSG.OPNEW_RA_A RA_WS12 RA_DEL12 PQRAR.RS_A tswe.
Definition T12MAX (L : asan_layout) (TSWMAX : credit) : credit := PQATSP.T12MAXG L 4 TSWMAX.
Definition CANDW : list Z -> list (list Z) := PQATSP.CANDW PQRAR.RS_A.
Definition CANDF (LR : HAR.layoutR) : list Z -> list (list Z) := PQATSP.CANDF LR RA_DEL12 PQRAR.RS_A.

(* [comment removed for export] *)
Lemma T12_bounds {SCFG_P : ScfgP} (L : asan_layout) (C : asan_statics_cells) (LR : HAR.layoutR) tswe TSWMAX TSRESA :
  PMA.layout L C -> PQATSP.tswe_laws tswe TSWMAX -> PMSP.credit_le (T12MAX L TSWMAX) TSRESA ->
  forall D RC, PMSP.credit_le PMSP.cr0 (T12 L LR tswe D RC) /\ PMSP.credit_le (T12 L LR tswe D RC) TSRESA.
Proof.
  intros LY TW GE D RC. pose proof (PMA.ly_cost L C LY) as (K8 & B3 & OV).
  assert (LNN : 0 <= hl_k_per_malloc L /\ 0 <= hl_b_lin L /\ 0 <= hl_b_overhead L) by (rewrite K8, B3, OV; lia).
  split; [exact (PQATSP.T12_nonneg L LR _ _ _ _ tswe TSWMAX LNN TW D RC)|].
  pose proof (PQATSP.T12_max L LR PQATSG.OPNEW_RA_A RA_WS12 RA_DEL12 PQRAR.RS_A tswe TSWMAX LNN TW D RC eq_refl) as M.
  change (Z.of_nat (length PQRAR.RS_A)) with 4 in M. unfold T12, T12MAX in *. unfold PMSP.credit_le in *. cbn [fst snd] in *. lia.
Qed.
End PQATSPa.

