(* [comment removed for export] *)
Lemma chain_cand (L : asan_layout) (ar : asan_run) (M : word -> option byte) lo sp r x8 RC RC0 :
  HAR.rchain L ar M lo sp RC -> cell_is (hl_segs L) M (sp - 8) 8 r -> 0 <= r < 2 ^ 64 ->
  cell_is (hl_segs L) M (sp - 16) 8 x8 -> 0 <= x8 < 2 ^ 64 -> HAR.rchain L ar M sp x8 RC0 ->
