Module PQATSPV.
Import PQATSP. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Abbreviation TAG_ENANO := NEM.TAG_ENANO.

(* [comment removed for export] *)
Definition tspv_laws (f : Z -> list (list Z) -> list Z -> credit) (MX : credit) : Prop :=
  forall t D RC, PMSP.credit_le PMSP.cr0 (f t D RC) /\ PMSP.credit_le (f t D RC) MX /\ (t <> NEM.TAG_ENANO -> f t D RC = PMSP.cr0)
                 /\ (forall D', incl D D' -> PMSP.credit_le (f t D' RC) (f t D RC)) /\ (forall RC', f t D RC' = f t D RC).

(* [comment removed for export] *)
Definition T12VG (L : asan_layout) (LR : HAR.layoutR) (gra raw rad : Z) (RS : list Z)
           (tswe : list (list Z) -> Z -> list Z -> credit) (tspV : Z -> list (list Z) -> list Z -> credit) (D : list (list Z)) (RC0 : list Z) : credit :=
  PM.credit_add (T12G L LR gra raw rad RS tswe D RC0) (tspV TAG_ENANO D RC0).
Definition T12VMAXG (L : asan_layout) (nrs : Z) (TSWMAX TSPVMAX : credit) : credit :=
  PM.credit_add (T12MAXG L nrs TSWMAX) TSPVMAX.

Section Laws.
Variables (L : asan_layout) (LR : HAR.layoutR) (gra raw rad : Z) (RS : list Z)
          (tswe : list (list Z) -> Z -> list Z -> credit) (TSWMAX : credit) (tspV : Z -> list (list Z) -> list Z -> credit) (TSPVMAX : credit).
Hypothesis LNN : 0 <= hl_k_per_malloc L /\ 0 <= hl_b_lin L /\ 0 <= hl_b_overhead L.
Hypothesis TW : tswe_laws tswe TSWMAX.
Hypothesis TVL : tspv_laws tspV TSPVMAX.
Let T12 := T12G L LR gra raw rad RS tswe.
Let T12V := T12VG L LR gra raw rad RS tswe tspV.

Lemma tv_nonneg t D RC : PMSP.credit_le PMSP.cr0 (tspV t D RC).
Proof. exact (proj1 (TVL t D RC)). Qed.
Lemma tv_max t D RC : PMSP.credit_le (tspV t D RC) TSPVMAX.
Proof. exact (proj1 (proj2 (TVL t D RC))). Qed.
Lemma tv_other t D RC : t <> TAG_ENANO -> tspV t D RC = PMSP.cr0.
Proof. exact (proj1 (proj2 (proj2 (TVL t D RC)))). Qed.
Lemma tv_anti t D D' RC : incl D D' -> PMSP.credit_le (tspV t D' RC) (tspV t D RC).
Proof. exact (proj1 (proj2 (proj2 (proj2 (TVL t D RC)))) D'). Qed.
Lemma tv_blind t D RC RC' : tspV t D RC' = tspV t D RC.
Proof. exact (proj2 (proj2 (proj2 (proj2 (TVL t D RC)))) RC'). Qed.

Lemma T12V_floor D RC0 : PMSP.credit_le (1, 0) (T12V D RC0).
Proof.
  pose proof (T12_floor L LR gra raw rad RS tswe TSWMAX LNN TW D RC0) as F. pose proof (tv_nonneg TAG_ENANO D RC0) as N.
  unfold T12V, T12VG, PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12V_nonneg D RC0 : PMSP.credit_le PMSP.cr0 (T12V D RC0).
Proof. pose proof (T12V_floor D RC0) as F. unfold PMSP.credit_le, PMSP.cr0 in *; cbn [fst snd] in *. lia. Qed.
Lemma T12V_max D RC0 : length (PQATSG.GKEYS LR gra) = 2%nat -> PMSP.credit_le (T12V D RC0) (T12VMAXG L (Z.of_nat (length RS)) TSWMAX TSPVMAX).
Proof.
  intros LG. pose proof (T12_max L LR gra raw rad RS tswe TSWMAX LNN TW D RC0 LG) as A. pose proof (tv_max TAG_ENANO D RC0) as B.
  unfold T12V, T12VG, T12VMAXG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12V_anti D D' RC0 : incl D D' -> PMSP.credit_le (T12V D' RC0) (T12V D RC0).
Proof.
  intros I. pose proof (T12_anti L LR gra raw rad RS tswe TSWMAX LNN TW D D' RC0 I) as A. pose proof (tv_anti TAG_ENANO D D' RC0 I) as B.
  unfold T12V, T12VG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12V_gpre D RC0 gk : In gk (PQATSG.GKEYS LR gra) -> PMSP.credit_le (PQATSG.gcostD L gk D 64) (T12V D RC0).
Proof.
  intros Hg. pose proof (T12_gpre L LR gra raw rad RS tswe TSWMAX LNN TW D RC0 gk Hg) as A. pose proof (tv_nonneg TAG_ENANO D RC0) as N.
  unfold T12V, T12VG, PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12V_grow D RC0 gk : In gk (PQATSG.GKEYS LR gra) ->
  PMSP.credit_le (PM.credit_add (T12V (gk :: D) RC0) (PM.credit_add (PQATSG.gcostD L gk D 64) (-1, 0))) (T12V D RC0).
Proof.
  intros Hg. pose proof (T12_grow L LR gra raw rad RS tswe TSWMAX LNN TW D RC0 gk Hg) as A.
  pose proof (tv_anti TAG_ENANO D (gk :: D) RC0 ltac:(intros z Hz; right; exact Hz)) as B.
  unfold T12V, T12VG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12V_ws D RC0 RC : In RC (CANDW RS RC0) ->
  PMSP.credit_le (PM.credit_add (tswe D raw RC) (1, 0)) (T12V D RC0)
  /\ (forall D', incl D D' ->
        PMSP.credit_le (PM.credit_add (T12V D' RC0) (tswe D raw RC)) (PM.credit_add (T12V D RC0) (tswe D' raw RC))).
Proof.
  intros Hin. destruct (T12_ws L LR gra raw rad RS tswe TSWMAX LNN TW D RC0 RC Hin) as [A1 A2]. pose proof (tv_nonneg TAG_ENANO D RC0) as N.
  split.
  - unfold T12V, T12VG, PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
  - intros D' I. pose proof (A2 D' I) as A. pose proof (tv_anti TAG_ENANO D D' RC0 I) as B.
    unfold T12V, T12VG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
Lemma T12V_free D RC0 Kt D2 : In Kt (CANDF LR rad RS RC0) -> incl (Kt :: D) D2 ->
  PMSP.credit_le (PM.credit_add (T12V D2 RC0) (if HAR.kin Kt D then (0, 0) else (1, 0))) (T12V D RC0).
Proof.
  intros Hin I2. pose proof (T12_free L LR gra raw rad RS tswe TSWMAX LNN TW D RC0 Kt D2 Hin I2) as A.
  pose proof (tv_anti TAG_ENANO D D2 RC0 ltac:(intros z Hz; apply I2; right; exact Hz)) as B.
  unfold T12V, T12VG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. destruct (HAR.kin Kt D); lia.
Qed.
(* [comment removed for export] *)
Lemma T12V_v t D RC0 RCv :
  PMSP.credit_le (tspV t D RCv) (T12V D RC0)
  /\ (forall D', incl D D' ->
        PMSP.credit_le (PM.credit_add (T12V D' RC0) (tspV t D RCv)) (PM.credit_add (T12V D RC0) (tspV t D' RCv))).
Proof.
  pose proof (T12_nonneg L LR gra raw rad RS tswe TSWMAX LNN TW D RC0) as N.
  destruct (Z.eq_dec t TAG_ENANO) as [-> | Ht].
  - split.
    + rewrite (tv_blind TAG_ENANO D RC0 RCv). unfold T12V, T12VG, PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
    + intros D' I. rewrite (tv_blind TAG_ENANO D RC0 RCv), (tv_blind TAG_ENANO D' RC0 RCv). pose proof (T12_anti L LR gra raw rad RS tswe TSWMAX LNN TW D D' RC0 I) as B.
      unfold T12V, T12VG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
  - rewrite (tv_other t D RCv Ht). split.
    + exact (T12V_nonneg D RC0).
    + intros D' I. rewrite (tv_other t D' RCv Ht). pose proof (T12V_anti D D' RC0 I) as A.
      unfold PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
(* [comment removed for export] *)
Lemma T12V_vf t D RC0 RCv :
  PMSP.credit_le (PM.credit_add (tspV t D RCv) (1, 0)) (T12V D RC0)
  /\ (forall D', incl D D' ->
        PMSP.credit_le (PM.credit_add (T12V D' RC0) (tspV t D RCv)) (PM.credit_add (T12V D RC0) (tspV t D' RCv))).
Proof.
  split; [| exact (proj2 (T12V_v t D RC0 RCv))].
  pose proof (T12_floor L LR gra raw rad RS tswe TSWMAX LNN TW D RC0) as F.
  destruct (Z.eq_dec t TAG_ENANO) as [-> | Ht].
  - rewrite (tv_blind TAG_ENANO D RC0 RCv). unfold T12V, T12VG, PMSP.credit_le, PM.credit_add in *; cbn [fst snd] in *. lia.
  - rewrite (tv_other t D RCv Ht). pose proof (tv_nonneg TAG_ENANO D RC0) as N.
    unfold T12V, T12VG, PMSP.credit_le, PMSP.cr0, PM.credit_add in *; cbn [fst snd] in *. lia.
Qed.
End Laws.

(* [comment removed for export] *)
Definition T12V (L : asan_layout) (LR : HAR.layoutR) (tswe : list (list Z) -> Z -> list Z -> credit) (tspV : Z -> list (list Z) -> list Z -> credit)
  : list (list Z) -> list Z -> credit :=
  T12VG L LR PQATSG.OPNEW_RA_A PQATSPa.RA_WS12 PQATSPa.RA_DEL12 PQRAR.RS_A tswe tspV.
Definition T12VMAX (L : asan_layout) (TSWMAX TSPVMAX : credit) : credit := T12VMAXG L 4 TSWMAX TSPVMAX.

Lemma T12V_unfold L LR tswe tspV D RC : T12V L LR tswe tspV D RC = PM.credit_add (PQATSPa.T12 L LR tswe D RC) (tspV TAG_ENANO D RC).
Proof. reflexivity. Qed.

(* [comment removed for export] *)
Lemma T12V_bounds {SCFG_P : ScfgP} (L : asan_layout) (C : asan_statics_cells) (LR : HAR.layoutR) tswe TSWMAX tspV TSPVMAX TSRESA :
  PMA.layout L C -> tswe_laws tswe TSWMAX -> tspv_laws tspV TSPVMAX -> PMSP.credit_le (T12VMAX L TSWMAX TSPVMAX) TSRESA ->
  forall D RC, PMSP.credit_le PMSP.cr0 (T12V L LR tswe tspV D RC) /\ PMSP.credit_le (T12V L LR tswe tspV D RC) TSRESA.
Proof.
  intros LY TW TVL GE D RC. pose proof (PMA.ly_cost L C LY) as (K8 & B3 & OV).
  assert (LNN : 0 <= hl_k_per_malloc L /\ 0 <= hl_b_lin L /\ 0 <= hl_b_overhead L) by (rewrite K8, B3, OV; lia).
  split; [exact (T12V_nonneg L LR _ _ _ _ tswe TSWMAX tspV TSPVMAX LNN TW TVL D RC)|].
  pose proof (T12V_max L LR PQATSG.OPNEW_RA_A PQATSPa.RA_WS12 PQATSPa.RA_DEL12 PQRAR.RS_A tswe TSWMAX tspV TSPVMAX LNN TW TVL D RC eq_refl) as M.
  change (Z.of_nat (length PQRAR.RS_A)) with 4 in M. unfold T12V, T12VMAX in *. unfold PMSP.credit_le in *. cbn [fst snd] in *. lia.
Qed.
(* [comment removed for export] *)
Lemma T12V_vlaw (L : asan_layout) (C : asan_statics_cells) (LR : HAR.layoutR) tswe TSWMAX tspV TSPVMAX {SCFG_P : ScfgP} :
  PMA.layout L C -> tswe_laws tswe TSWMAX -> tspv_laws tspV TSPVMAX ->
  forall t D RC RCv,
    PMSP.credit_le (tspV t D RCv) (T12V L LR tswe tspV D RC)
    /\ (forall D', incl D D' -> PMSP.credit_le (PM.credit_add (T12V L LR tswe tspV D' RC) (tspV t D RCv)) (PM.credit_add (T12V L LR tswe tspV D RC) (tspV t D' RCv))).
Proof.
  intros LY TW TVL t D RC RCv. pose proof (PMA.ly_cost L C LY) as (K8 & B3 & OV).
  assert (LNN : 0 <= hl_k_per_malloc L /\ 0 <= hl_b_lin L /\ 0 <= hl_b_overhead L) by (rewrite K8, B3, OV; lia).
  exact (T12V_v L LR PQATSG.OPNEW_RA_A PQATSPa.RA_WS12 PQATSPa.RA_DEL12 PQRAR.RS_A tswe TSWMAX tspV TSPVMAX LNN TW TVL t D RC RCv).
Qed.
Lemma T12V_vflaw (L : asan_layout) (C : asan_statics_cells) (LR : HAR.layoutR) tswe TSWMAX tspV TSPVMAX {SCFG_P : ScfgP} :
  PMA.layout L C -> tswe_laws tswe TSWMAX -> tspv_laws tspV TSPVMAX ->
  forall t D RC RCv,
    PMSP.credit_le (PM.credit_add (tspV t D RCv) (1, 0)) (T12V L LR tswe tspV D RC)
    /\ (forall D', incl D D' -> PMSP.credit_le (PM.credit_add (T12V L LR tswe tspV D' RC) (tspV t D RCv)) (PM.credit_add (T12V L LR tswe tspV D RC) (tspV t D' RCv))).
Proof.
  intros LY TW TVL t D RC RCv. pose proof (PMA.ly_cost L C LY) as (K8 & B3 & OV).
  assert (LNN : 0 <= hl_k_per_malloc L /\ 0 <= hl_b_lin L /\ 0 <= hl_b_overhead L) by (rewrite K8, B3, OV; lia).
  exact (T12V_vf L LR PQATSG.OPNEW_RA_A PQATSPa.RA_WS12 PQATSPa.RA_DEL12 PQRAR.RS_A tswe TSWMAX tspV TSPVMAX LNN TW TVL t D RC RCv).
Qed.
